-- 업무관리 예시 카드 — 보드가 비어 있을 때만(다시 돌려도 늘지 않는다). 일정은 설치한 날 기준(달력 보기에 바로 보이게)
INSERT INTO work_items (adminId, Json, parentWorkId, hostingId, groupKey)
SELECT a, j, p, h, g FROM (
SELECT 0 AS a, JSON_SET('{"title": "업무관리 사용법 — 이 카드부터 읽어 보세요", "category": {"c1": 2, "c2": 0, "c3": 0}, "status": 10, "kind": 1, "html": "# 업무관리 사용법\\n\\n할 일을 **카드**로 만들고 상태(백로그 → 진행중 → 완료)를 옮기며 관리해요.\\n\\n- **새 카드**: 오른쪽 위 「추가」\\n- **보기 바꾸기**: 위쪽 「테이블 / 칸반」\\n- **분류**: 대분류(기획·개발·운영)와 「분류」(기능·버그·보안…) — 설정 › 공통 코드 › 업무관리 에서 고친다\\n- **댓글·첨부**: 카드를 열고 아래 메모·파일\\n- **Claude 와 함께**: 카드 번호를 알려 주면 Claude 가 읽고 진행 상황을 댓글로 남겨요\\n\\n예시 카드들은 다 보고 나면 지워도 돼요.", "desc": "", "adminIds": [], "tags": []}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 0 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 0 DAY, '%Y-%m-%d'))) AS j, 0 AS p, 'ZBD' AS h, 'TASK' AS g
UNION ALL SELECT 0, JSON_SET('{"title": "관리자 비밀번호 바꾸고 지문·얼굴 로그인 등록", "category": {"c1": 3, "c2": 0, "c3": 0}, "status": 1, "kind": 3, "html": "마이페이지에서 비밀번호를 바꾸고, 지문·얼굴 로그인을 등록하세요.", "desc": "", "adminIds": [], "tags": ["보안"]}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 0 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 1 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
UNION ALL SELECT 0, JSON_SET('{"title": "사이트 이름·회사 정보 정하기", "category": {"c1": 3, "c2": 0, "c3": 0}, "status": 1, "kind": 5, "html": "설정 › 환경 설정 에서 사이트 이름·회사 정보·로고를 정하세요. 바닥글(사업자 정보)에 그대로 나와요.", "desc": "", "adminIds": [], "tags": []}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 1 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 3 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
UNION ALL SELECT 0, JSON_SET('{"title": "약관의 [회사명]·[시행일]·[연락처] 고치기", "category": {"c1": 3, "c2": 0, "c3": 0}, "status": 5, "kind": 5, "html": "게시판 › 약관 의 이용약관·개인정보 처리방침에서 자리표를 실제 값으로 바꾸세요.\\n\\n**꺼내는 조건**: 사업자 정보(회사명·연락처)가 정해지면.", "desc": "", "adminIds": [], "tags": ["약관"]}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 2 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 5 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
UNION ALL SELECT 0, JSON_SET('{"title": "홈 화면 만들기", "category": {"c1": 2, "c2": 0, "c3": 0}, "status": 10, "kind": 1, "html": "`zbd-fe-svelte5/src/routes/(user)/(site)/+page.svelte` 를 고쳐 내 홈을 만들어요. Claude 에게 「홈에 서비스 소개 섹션 넣어 줘」 처럼 시켜도 돼요.", "desc": "", "adminIds": [], "tags": ["화면"]}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 0 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 7 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
UNION ALL SELECT 0, JSON_SET('{"title": "첫 공지 올리기", "category": {"c1": 1, "c2": 0, "c3": 0}, "status": 1, "kind": 1, "html": "게시판 › 공지사항 에서 첫 공지를 쓰면 /board/notice 에 나와요.", "desc": "", "adminIds": [], "tags": []}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL 3 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL 3 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
UNION ALL SELECT 0, JSON_SET('{"title": "예시 — 다 끝난 카드", "category": {"c1": 1, "c2": 0, "c3": 0}, "status": 30, "kind": 1, "html": "끝난 일은 「완료」 로 옮겨 두면 기록으로 남아요.", "desc": "", "adminIds": [], "tags": []}', '$.schedule', JSON_OBJECT('from', DATE_FORMAT(CURDATE() + INTERVAL -3 DAY, '%Y-%m-%d'), 'to', DATE_FORMAT(CURDATE() + INTERVAL -1 DAY, '%Y-%m-%d'))), 0, 'ZBD', 'TASK'
) t WHERE NOT EXISTS (SELECT 1 FROM work_items WHERE hostingId = 'ZBD' AND groupKey = 'TASK');

-- 공지사항 예시 2개(첫 관리자 글) — 첫 글은 상단 고정 + 첨부파일(시작 가이드, run_dev.sh 가 보안 폴더에 넣는다). 이미 있으면 넣지 않는다
INSERT IGNORE INTO posts (postId, adminId, groupKey, groupSubKey, title, json, jsonUser, status, hostingId, createdAt, updatedAt) VALUES
('notice01', 1, 'NOTICE', '', '사이트를 열었어요', '{"body": "<h2>사이트를 열었어요</h2><p>zbd-starter 로 만든 사이트의 첫 공지예요. 공지는 관리자 화면 <b>게시판 › 공지사항</b> 에서 쓰고 고칩니다.</p><p style=\\"text-align:center\\"><img src=\\"/assets/starter/sample.svg\\" alt=\\"예시 그림\\" style=\\"max-width:100%\\"></p><ul><li>글 위에 고정하려면 글 설정의 「상단 고정」</li><li>첨부파일은 글 설정 아래 「파일첨부」 — 이 글에는 시작 가이드가 붙어 있어요</li></ul>", "isFixTop": true, "files": [{"fileName": "시작 가이드.md", "hostingId": "ZBD"}]}', '{}', 0, 'ZBD', CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
('notice02', 1, 'NOTICE', '', '공지 쓰는 법', '{"body": "<h2>공지 쓰는 법</h2><ol><li>관리자 화면 → <b>게시판 › 공지사항</b></li><li>오른쪽 위 「글쓰기」</li><li>제목·본문을 쓰고 저장하면 <a href=\\"/board/notice\\">/board/notice</a> 에 바로 나와요</li></ol><p>이 예시 공지들은 확인한 뒤 지워도 됩니다.</p>"}', '{}', 0, 'ZBD', CURRENT_TIMESTAMP() - INTERVAL 1 MINUTE, CURRENT_TIMESTAMP() - INTERVAL 1 MINUTE);
